async function handler(input) {
  const { client_id, client_secret, env } = input;
  const endpoint = (env === 'PRODUCTION')
    ? 'https://api.cashfree.com/pg/orders?limit=1'
    : 'https://sandbox.cashfree.com/pg/orders?limit=1';

  const response = await fetch(endpoint, {
    method: 'GET',
    headers: {
      'x-api-version': '2023-08-01',
      'x-client-id': client_id,
      'x-client-secret': client_secret
    }
  });

  const data = await response.json();
  if (!response.ok) {
    return { valid: false, error: data.message || 'Authentication failed' };
  }
  return { valid: true, message: 'Cashfree credentials verified successfully', env: env || 'SANDBOX' };
}
